mapper.select:
SELECT u.user_id as "userId", u.employee_no as "employeeNo", COALESCE(kps.person_name, u.user_name) as "userName", COALESCE(kps.org_code, u.org_code) as "orgCode", COALESCE(kps.org_name, u.org_name) as "orgName", COALESCE(kps.position_name, u.position_name) as "positionName", COALESCE(kps.duty_name, u.duty_name) as "dutyName", COALESCE(kps.employment_status, u.employment_status) as "employmentStatus", COALESCE(kps.retirement_date, u.retirement_date) as "retirementDate", COALESCE(kps.last_synced_at, u.last_synced_at) as "lastSyncedAt", u.system_use_yn as "systemUseYn", CASE WHEN kps.employee_no IS NULL THEN 'LOCAL' ELSE 'KORUS_MOCK' END as "personnelSource", COALESCE(string_agg(ura.role_code, ',' ORDER BY ura.role_code), '') as "roleCodes" FROM user_account u LEFT JOIN korus_personnel_snapshot kps ON kps.employee_no = u.employee_no AND kps.snapshot_status = 'ACTIVE' LEFT JOIN user_role_assignment ura ON ura.user_id = u.user_id AND ura.status = 'ACTIVE'
(u.employee_no LIKE CONCAT('%', #{filter}, '%') OR COALESCE(kps.person_name, u.user_name) LIKE CONCAT('%', #{filter}, '%') OR COALESCE(kps.org_name, u.org_name) LIKE CONCAT('%', #{filter}, '%') OR COALESCE(kps.position_name, u.position_name) LIKE CONCAT('%', #{filter}, '%') OR ura.role_code LIKE CONCAT('%', #{filter}, '%') OR u.system_use_yn = #{filter})
GROUP BY u.user_id, u.employee_no, u.user_name, u.org_code, u.org_name, u.position_name, u.duty_name, u.employment_status, u.retirement_date, u.last_synced_at, u.system_use_yn, kps.employee_no, kps.person_name, kps.org_code, kps.org_name, kps.position_name, kps.duty_name, kps.employment_status, kps.retirement_date, kps.last_synced_at ORDER BY u.employee_no LIMIT #{size} OFFSET #{offset}

SELECT role_code as "roleCode", role_name as "roleName", purpose, grant_criteria as "grantCriteria", default_data_scope as "defaultDataScope", use_yn as "useYn" FROM role
(role_code LIKE CONCAT('%', #{filter}, '%') OR role_name LIKE CONCAT('%', #{filter}, '%') OR purpose LIKE CONCAT('%', #{filter}, '%'))
ORDER BY role_code LIMIT #{size} OFFSET #{offset}

SELECT mp.permission_id as "permissionId", mp.target_type as "targetType", mp.target_id as "targetId", m.menu_id as "menuId", m.menu_name as "menuName", m.parent_menu_id as "parentMenuId", mp.can_read as "canRead", mp.can_create as "canCreate", mp.can_update as "canUpdate", mp.can_disable as "canDisable", mp.can_access as "canAccess"
FROM menu_permission mp JOIN menu m ON m.menu_id=mp.menu_id

  mp.target_type = #{targetType}
  AND mp.target_id = #{targetId}

ORDER BY m.sort_order, m.menu_id

SELECT menu_id as "menuId", parent_menu_id as "parentMenuId", menu_name as "menuName", screen_id as "screenId", route_path as "routePath", icon_name as "iconName", business_area as "businessArea", description, sort_order as "sortOrder", use_yn as "useYn", status FROM menu
(menu_id LIKE CONCAT('%', #{filter}, '%') OR menu_name LIKE CONCAT('%', #{filter}, '%') OR route_path LIKE CONCAT('%', #{filter}, '%') OR use_yn = #{filter})
ORDER BY parent_menu_id NULLS FIRST, sort_order, menu_id LIMIT #{size} OFFSET #{offset}

SELECT group_id as "groupId", group_name as "groupName", description, managing_department as "managingDepartment", use_yn as "useYn" FROM code_group
(group_id LIKE CONCAT('%', #{filter}, '%') OR group_name LIKE CONCAT('%', #{filter}, '%') OR managing_department LIKE CONCAT('%', #{filter}, '%'))
ORDER BY group_id LIMIT #{size} OFFSET #{offset}
